'use client'

import {
  createContext,
  useContext,
  useEffect,
  useId,
  useRef,
  useState,
  type ComponentProps,
  type PointerEvent as ReactPointerEvent,
  type ReactElement,
  type ReactNode,
  type RefObject,
} from 'react'
import { useRender } from '@base-ui/react/use-render'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import { Tooltip } from '../../overlays/Tooltip'
import { ShellContext } from './TopBar'
import styles from './NavSidebar.module.css'

export interface NavSidebarItem {
  type?: 'item'
  label: string
  href?: string
  /** Needed to show in the rail: an item without one is left out of it. */
  icon?: ReactNode
  /** A count or short tag after the label, e.g. unread items. */
  badge?: ReactNode
  /** Replaces the `<a>`, e.g. a router's `<Link to="…" />`. */
  render?: ReactElement
}
/** A category: a named list of items. */
export interface NavSidebarGroup {
  type: 'group'
  label: string
  items: NavSidebarItem[]
  /** At the end of the label row, e.g. an icon Button that adds an item. Shows on hover and focus. */
  action?: ReactNode
  /** The label becomes a button that shows and hides the items. */
  isCollapsible?: boolean
  isCollapsed?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean) => void
  /** Show this many items and a "Show more" button for the rest. */
  limit?: number
}
export type NavSidebarEntry = NavSidebarItem | NavSidebarGroup

export interface NavSidebarProps extends Omit<ComponentProps<'nav'>, 'children'> {
  items: NavSidebarEntry[]
  /** The href of the page the reader is on: that item gets aria-current="page". */
  currentHref?: string
  /**
   * The logo, in the top row with the collapse button. Inside an AppShell's
   * sidebar layout the shell passes its own `brand` here.
   */
  brand?: ReactNode
  /** Under the logo, e.g. a tenant switcher and search, built from NavSidebarButton. Stays in the rail. */
  header?: ReactNode
  /** Pinned to the bottom, e.g. the account, notifications and help. Stays in the rail, stacked. */
  footer?: ReactNode
  /** An icon rail: labels move into tooltips; items without an icon are left out. */
  isCollapsed?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean) => void
  /** Show a button that collapses and expands the sidebar. */
  isCollapsible?: boolean
  /** The nav landmark's name. */
  'aria-label'?: string
}

/** Whether the sidebar is the rail, for the parts in its header and footer. */
const RailContext = createContext(false)

/** `null`, `false` and `undefined` render nothing. */
const given = (node: ReactNode) => node != null && node !== false

function ItemLink({ item, current, collapsed }: { item: NavSidebarItem; current: boolean; collapsed: boolean }) {
  // Collapsed hides the badge too, so a count or short tag joins the name.
  const name =
    typeof item.badge === 'string' || typeof item.badge === 'number' ? `${item.label}, ${item.badge}` : item.label
  const link = useRender({
    render: item.render,
    defaultTagName: 'a',
    props: {
      href: item.href,
      className: cn(styles.item, current && styles.current),
      'aria-current': current ? ('page' as const) : undefined,
      // Collapsed, the label is gone from view but must still name the link;
      // with a badge, the name puts a comma between them ("Inbox, 12").
      'aria-label': collapsed || name !== item.label ? name : undefined,
      children: (
        <>
          {item.icon && (
            <span className={styles.icon} aria-hidden="true">
              {item.icon}
            </span>
          )}
          <span className={styles.label}>{item.label}</span>
          {item.badge !== undefined && <span className={styles.badge}>{item.badge}</span>}
        </>
      ),
    },
  })
  return collapsed ? (
    <Tooltip content={name} side="right">
      {link}
    </Tooltip>
  ) : (
    link
  )
}

export interface NavSidebarButtonProps extends ComponentProps<'button'> {
  icon: ReactNode
  /** The visible text, and the button's name in the rail. */
  label: string
  /** A second, quieter line, e.g. the account's role. */
  description?: ReactNode
  /** A count after the label, e.g. unread notifications. Joins the name in the rail. */
  badge?: ReactNode
  /** A chevron or a shortcut hint: right after the label for `switcher`, at the far end otherwise. */
  end?: ReactNode
  /**
   * `ghost`: a row like an item (notifications, help, the account).
   * `switcher`: the label in medium weight with its chevron right after it,
   * for a tenant or workspace switcher. `field`: drawn as an input, for a
   * search button that opens a command palette.
   */
  appearance?: 'ghost' | 'switcher' | 'field'
}

/**
 * A row for the header and footer: a tenant switcher, a search button, the
 * account. A button, so it can be a Menu's or Popover's trigger; in the rail
 * it is its icon, named by its label.
 */
export function NavSidebarButton({
  icon,
  label,
  description,
  badge,
  end,
  appearance = 'ghost',
  className,
  ...props
}: NavSidebarButtonProps) {
  const collapsed = useContext(RailContext)
  // Collapsed hides the badge, so a count joins the name, as on an item.
  const name = typeof badge === 'string' || typeof badge === 'number' ? `${label}, ${badge}` : label
  const button = (
    <button
      type="button"
      className={cn(styles.item, styles.button, styles[appearance], className)}
      aria-label={collapsed || name !== label ? name : undefined}
      {...props}
    >
      <span className={styles.icon} aria-hidden="true">
        {icon}
      </span>
      <span className={styles.text}>
        <span className={styles.label}>{label}</span>
        {description && <span className={styles.description}>{description}</span>}
      </span>
      {badge !== undefined && <span className={styles.badge}>{badge}</span>}
      {/* A chevron or a shortcut hint: shown, not part of the name ("Search", not "Search⌘K"). */}
      {end && (
        <span className={styles.end} aria-hidden="true">
          {end}
        </span>
      )}
    </button>
  )
  return collapsed ? (
    <Tooltip content={name} side="right">
      {button}
    </Tooltip>
  ) : (
    button
  )
}

/** Runs of ungrouped items become one list; groups stay as they are. */
function sections(items: NavSidebarEntry[]) {
  const out: (NavSidebarItem[] | NavSidebarGroup)[] = []
  for (const entry of items) {
    if (entry.type === 'group') out.push(entry)
    else if (Array.isArray(out.at(-1))) (out.at(-1) as NavSidebarItem[]).push(entry)
    else out.push([entry])
  }
  return out
}

function Group({
  group,
  id,
  collapsed,
  list,
  currentHref,
}: {
  group: NavSidebarGroup
  id: string
  collapsed: boolean
  list: (entries: NavSidebarItem[], labelledBy?: string) => ReactNode
  currentHref?: string
}) {
  const [closedState, setClosedState] = useState(group.defaultCollapsed ?? false)
  const closed = group.isCollapsed ?? closedState
  const toggle = () => {
    setClosedState(!closed)
    group.onCollapsedChange?.(!closed)
  }
  // Open from the start when the current page is past the limit, so it is never hidden.
  const [showAll, setShowAll] = useState(
    () => group.limit !== undefined && group.items.findIndex((it) => it.href === currentHref) >= group.limit,
  )
  // The rail has no label to reopen a category or a "Show more" to press, so it shows every item it can.
  const items = collapsed
    ? group.items
    : group.limit !== undefined && !showAll
      ? group.items.slice(0, group.limit)
      : group.items
  const hasMore = !collapsed && group.limit !== undefined && group.items.length > group.limit
  const hidden = closed && !collapsed

  return (
    // The label names the list ("Pinned, list, 3 items") rather than being a
    // heading, so it cannot break the page's outline.
    <div className={styles.group}>
      <div className={styles.groupHead}>
        {group.isCollapsible ? (
          <button
            type="button"
            id={`${id}-label`}
            className={cn(styles.groupLabel, styles.groupToggle)}
            aria-expanded={!closed}
            aria-controls={`${id}-list`}
            onClick={toggle}
          >
            {group.label}
            <Icon name={closed ? 'chevron-right' : 'chevron-down'} className={styles.groupChevron} />
          </button>
        ) : (
          <div id={`${id}-label`} className={styles.groupLabel}>
            {group.label}
          </div>
        )}
        {given(group.action) && <div className={styles.groupAction}>{group.action}</div>}
      </div>
      <div id={`${id}-list`} hidden={hidden}>
        {list(items, `${id}-label`)}
        {hasMore && (
          <button type="button" className={cn(styles.item, styles.button, styles.more)} onClick={() => setShowAll(!showAll)}>
            <span className={styles.label}>{showAll ? 'Show less' : 'Show more'}</span>
          </button>
        )}
      </div>
    </div>
  )
}

export function NavSidebar({
  items,
  currentHref,
  brand: brandProp,
  header,
  footer,
  isCollapsed,
  defaultCollapsed = false,
  onCollapsedChange,
  isCollapsible = false,
  'aria-label': ariaLabel = 'Main',
  className,
  ...props
}: NavSidebarProps) {
  const [collapsedState, setCollapsedState] = useState(defaultCollapsed)
  const shell = useContext(ShellContext)
  // In an App Shell under 64rem it is always the rail: expanded, it would
  // cover most of a phone. The hover preview still floats over the page, but
  // there is no expanding or docking it there.
  const isRail = shell.isNarrow || (isCollapsed ?? collapsedState)
  const canToggle = isCollapsible && !shell.isNarrow
  const setRail = (next: boolean) => {
    setCollapsedState(next)
    onCollapsedChange?.(next)
  }
  const brand = given(brandProp) ? brandProp : shell.sidebarBrand
  const id = useId()
  const slotRef = useRef<HTMLDivElement>(null)
  const peek = usePeek(isRail, slotRef)
  // While the pointer rests on the rail, the full sidebar floats over the
  // page (as in the Claude apps); its button docks it.
  const collapsed = isRail && !peek.isOpen
  const list = (entries: NavSidebarItem[], labelledBy?: string) => (
    <ul className={styles.list} aria-labelledby={labelledBy}>
      {entries.map((item) => (
        <li key={item.href ?? item.label}>
          <ItemLink item={item} current={item.href !== undefined && item.href === currentHref} collapsed={collapsed} />
        </li>
      ))}
    </ul>
  )
  // The rail shows icons only, so an item without one has nothing to show there.
  const shown = collapsed
    ? sections(items)
        .map((s) => (Array.isArray(s) ? s.filter((it) => it.icon) : { ...s, items: s.items.filter((it) => it.icon) }))
        .filter((s) => (Array.isArray(s) ? s : s.items).length > 0)
    : sections(items)

  return (
    <RailContext.Provider value={collapsed}>
      {/* The slot keeps the rail's width in the layout while the preview
          floats; expanded it is display: contents and lays out nothing. */}
      <div
        ref={slotRef}
        className={cn(styles.slot, isRail && styles.railSlot)}
        onPointerEnter={peek.onPointerEnter}
        onPointerLeave={peek.onPointerLeave}
      >
        <nav
          aria-label={ariaLabel}
          className={cn(styles.sidebar, collapsed && styles.collapsed, peek.isOpen && styles.peek, className)}
          {...props}
        >
          {(given(brand) || canToggle) && (
            <div className={cn(styles.brandRow, given(brand) && styles.withBrand)}>
              {given(brand) && <div className={styles.brand}>{brand}</div>}
              {canToggle && (
                <button
                  type="button"
                  className={styles.toggle}
                  aria-expanded={!isRail}
                  aria-label={peek.isOpen ? 'Keep sidebar open' : isRail ? 'Expand sidebar' : 'Collapse sidebar'}
                  onClick={() => {
                    peek.close()
                    setRail(!isRail)
                  }}
                >
                  <Icon name={isRail ? 'sidebar-expand' : 'sidebar-collapse'} />
                </button>
              )}
            </div>
          )}
          {given(header) && <div className={styles.header}>{header}</div>}
          <div className={styles.body}>
            {shown.map((section, i) =>
              Array.isArray(section) ? (
                <div key={i}>{list(section)}</div>
              ) : (
                <Group
                  key={section.label}
                  group={section}
                  id={`${id}-group-${i}`}
                  collapsed={collapsed}
                  list={list}
                  currentHref={currentHref}
                />
              ),
            )}
          </div>
          {given(footer) && <div className={styles.footer}>{footer}</div>}
        </nav>
      </div>
    </RailContext.Provider>
  )
}

/** Hover delay before the rail previews the full sidebar, so passing the pointer across does not flash it. */
const PEEK_DELAY = 120

/**
 * The rail's hover preview. Mouse only: touch has no hover, and keyboard
 * focus reaches the same links in the rail (the expand button docks it). It
 * stays open while one of its menus is, and closes once the pointer is
 * elsewhere and no menu is open.
 */
/** Whether a menu or popover opened from inside the element is still open. */
const hasOpenMenu = (el: HTMLElement | null) => el?.querySelector('[aria-haspopup][aria-expanded="true"]') != null

function usePeek(isRail: boolean, ref: RefObject<HTMLDivElement | null>) {
  const [isOpen, setIsOpen] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)
  const close = () => {
    clearTimeout(timer.current)
    setIsOpen(false)
  }
  useEffect(() => () => clearTimeout(timer.current), [])
  // A menu opened from the preview keeps it; once that menu closes, the next
  // pointer move outside closes the preview.
  useEffect(() => {
    if (!isOpen) return
    const onMove = (e: PointerEvent) => {
      if (!ref.current?.contains(e.target as Node) && !hasOpenMenu(ref.current)) setIsOpen(false)
    }
    document.addEventListener('pointermove', onMove)
    return () => document.removeEventListener('pointermove', onMove)
  }, [isOpen, ref])
  return {
    // Only the rail previews; a stale open state from before docking is ignored.
    isOpen: isRail && isOpen,
    close,
    onPointerEnter: (e: ReactPointerEvent<HTMLDivElement>) => {
      if (!isRail || e.pointerType !== 'mouse') return
      clearTimeout(timer.current)
      timer.current = setTimeout(() => setIsOpen(true), PEEK_DELAY)
    },
    onPointerLeave: () => {
      clearTimeout(timer.current)
      if (!hasOpenMenu(ref.current)) setIsOpen(false)
    },
  }
}

/* --sidebar-width is a token (it follows density, and an AppShell sizes the
   logo's cell in its top bar by it). An AppShell sets --sidebar-background
   and --sidebar-border to draw the fill and edge itself, and the
   --sidebar-* colours below for its surfaces (white: a brand-tint current
   item; transparent: whatever the canvas needs). */
.sidebar {
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  inline-size: var(--sidebar-width);
  block-size: 100%;
  padding: var(--space-inline);
  border-inline-end: var(--sidebar-border, 1px solid var(--border));
  background: var(--sidebar-background, var(--surface-filled));
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--foreground);
  transition: inline-size var(--duration-base);
}

/* Expanded, the slot lays out nothing. As the rail it holds the rail's width
   in the layout, so the hover preview can float over the page. */
.slot {
  display: contents;
}
.railSlot {
  position: relative;
  display: flex;
  flex-shrink: 0;
  inline-size: calc(var(--control-md) + 2 * var(--space-inline));
}

/* The hover preview: the full sidebar over the page, on an opaque fill (the
   AppShell names one for a transparent sidebar) with a shadow. */
.peek {
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  z-index: var(--layer-sticky);
  background: var(--sidebar-peek-background, var(--sidebar-background, var(--surface-filled)));
  box-shadow: var(--shadow-lg);
  animation: peek-in var(--duration-base) ease-out;
}
@keyframes peek-in {
  from {
    opacity: 0;
    translate: calc(-1 * var(--space-2)) 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .peek {
    animation: none;
  }
}

/* The rail: one square row plus the padding either side. */
.collapsed {
  /* stylelint-disable-next-line zweihander/no-token-shadow -- the rail narrows the token, and the AppShell top bar reads it */
  --sidebar-width: calc(var(--control-md) + 2 * var(--space-inline));
}

/* The top row: the logo and the collapse button. As tall as the AppShell's
   top bar from the very top (it cancels the sidebar's padding), with the
   logo two --space-inline in, so the logo sits where it would in the
   top-bar layout and lines up with the nav icons. */
.brandRow {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--space-2);
  margin-block-end: var(--space-inline);
}
.withBrand {
  justify-content: space-between;
  margin-block: calc(-1 * var(--space-inline)) 0;
  block-size: calc(var(--control-md) + 2 * var(--space-cluster));
}
.brand {
  display: flex;
  flex: 1;
  align-items: center;
  min-inline-size: 0;
  padding-inline-start: var(--space-inline);
  overflow: hidden;
}
/* In the rail the logo keeps its place, cut to the rail's width (so a logo
   should lead with its mark), and the expand button takes its spot on hover
   or focus, as in the Claude apps. */
.collapsed .withBrand {
  display: grid;
}
.collapsed .withBrand > * {
  grid-area: 1 / 1;
}
.collapsed .withBrand .toggle {
  justify-self: center;
  opacity: 0;
}
.collapsed .withBrand:hover .toggle,
.collapsed .withBrand .toggle:focus-visible {
  opacity: 1;
}
.collapsed .withBrand:hover .brand,
.collapsed .withBrand:has(.toggle:focus-visible) .brand {
  visibility: hidden;
}

/* Under the logo: a tenant switcher, search. The first item follows at the
   header's own row gap, so header and nav read as one column. */
.header {
  display: flex;
  flex-direction: column;
  gap: var(--space-inline);
  margin-block-end: var(--space-inline);
}

.toggle {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  inline-size: var(--control-md);
  block-size: var(--control-md);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--radius-control);
  background: transparent;
  color: var(--muted-foreground);
  font-size: var(--icon-md);
  cursor: var(--cursor-button);
}
.toggle:hover {
  /* An overlay, not --accent: in dark the sidebar's own --surface-filled is
     the same gray-800 as --accent, so an opaque hover fill vanished. */
  background: var(--sidebar-hover, var(--hover-overlay));
  color: var(--accent-foreground);
}

.body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: var(--space-group);
  min-block-size: 0;
  /* The body reaches through the sidebar's end padding, so its scrollbar
     sits against the sidebar's edge as in the Claude apps; the gutter is
     always kept, so rows keep their width whether or not the list scrolls. */
  margin-inline-end: calc(-1 * var(--space-inline));
  overflow-y: auto;
  scrollbar-gutter: stable;
  --thumb: transparent;
}
/* No track, a 6px rounded thumb (an 8px bar less a 1px clipped border),
   shown while the sidebar is hovered or holds focus. */
.sidebar:hover .body,
.body:focus-within {
  --thumb: color-mix(in oklch, var(--foreground) 22%, transparent);
}
.body::-webkit-scrollbar {
  inline-size: calc(var(--space-2));
}
.body::-webkit-scrollbar-track {
  background: transparent;
}
.body::-webkit-scrollbar-thumb {
  border: 1px solid transparent;
  border-radius: var(--radius-pill);
  background: var(--thumb) padding-box;
}
.body::-webkit-scrollbar-thumb:hover {
  background-color: color-mix(in oklch, var(--foreground) 38%, transparent);
}
/* Firefox has no ::-webkit-scrollbar; Chrome would drop the rules above once
   scrollbar-color is set, so this is kept to browsers without them. */
@supports not selector(::-webkit-scrollbar) {
  .body {
    scrollbar-width: thin;
    scrollbar-color: var(--thumb) transparent;
  }
}
/* The rail is too narrow to give up a gutter: it scrolls with no bar. */
.collapsed .body {
  margin-inline-end: 0;
  scrollbar-gutter: auto;
  scrollbar-width: none;
}
.collapsed .body::-webkit-scrollbar {
  display: none;
}

.group {
  display: flex;
  flex-direction: column;
  gap: var(--space-stack);
}

.groupHead {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  min-block-size: var(--box-sm);
}
.groupLabel {
  display: flex;
  flex: 1;
  align-items: center;
  gap: var(--space-1);
  min-inline-size: 0;
  margin: 0;
  padding: 0 var(--space-inline);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--muted-foreground);
  white-space: nowrap;
}
.groupToggle {
  align-self: stretch;
  border: 0;
  border-radius: var(--radius-control);
  background: transparent;
  font-family: inherit;
  text-align: start;
  cursor: var(--cursor-button);
}
.groupToggle:hover {
  color: var(--accent-foreground);
}
/* The chevron shows on hover and focus only, as in the Claude apps; the
   state is still aria-expanded. */
.groupChevron {
  font-size: var(--icon-sm);
  opacity: 0;
}
.groupToggle:hover .groupChevron,
.groupToggle:focus-visible .groupChevron,
.groupToggle[aria-expanded='false'] .groupChevron {
  opacity: 1;
}
/* The action (add an item) shows while the category is hovered or focused. */
.groupAction {
  display: flex;
  flex-shrink: 0;
  opacity: 0;
}
.group:hover .groupAction,
.groupAction:focus-within,
.groupAction:has([aria-expanded='true']) {
  opacity: 1;
}
/* In the rail the head is gone, but the label still names the list, and
   a rule marks where the group starts. */
.collapsed .groupHead {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
}
.collapsed .groupAction {
  display: none;
}
.collapsed .group + .group::before,
.collapsed .body > * + .group::before {
  content: '';
  block-size: 1px;
  margin: 0 var(--space-2) var(--space-1);
  background: var(--border);
}

.list {
  display: flex;
  flex-direction: column;
  /* 2px in every density, so hover and current fills never touch. */
  gap: var(--space-0-5);
  margin: 0;
  padding: 0;
  list-style: none;
}

.item {
  display: flex;
  align-items: center;
  gap: var(--space-inline);
  box-sizing: border-box;
  min-block-size: var(--control-md);
  padding: 0 var(--space-inline);
  border-radius: var(--radius-control);
  /* A step quieter than body text, as in the Claude apps; hover and the
     current item come up to --foreground. */
  color: var(--subtle-foreground);
  text-decoration: none;
  white-space: nowrap;
  cursor: var(--cursor-link);
}
.item:hover {
  background: var(--sidebar-hover, var(--hover-overlay));
  color: var(--accent-foreground);
}
.item:focus-visible,
.toggle:focus-visible,
.groupToggle:focus-visible {
  outline: var(--focus-width) solid var(--ring);
  outline-offset: var(--focus-offset-inset);
}

/* The current page: a --selected fill, a step past the hover fill so the
   two never read alike, plus medium weight and aria-current. No accent and
   no edge: selection is a place in the list, not a call to action. */
.current,
.current:hover {
  background: var(--sidebar-selected, var(--selected));
  color: var(--sidebar-selected-foreground, var(--foreground));
  font-weight: 500;
}

/* Every leading visual (a nav icon, the tenant's and the account's avatar)
   sits in an --icon-md wide slot after the row's padding, so their centres
   share one vertical line; a bigger one overflows the slot evenly. */
.icon {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  inline-size: var(--icon-md);
  font-size: var(--icon-md);
  color: var(--muted-foreground);
}
/* An Avatar in a NavSidebarButton is 20px in every density: a row like the
   others, not a profile card. Avatar xs is 24px at Default. */
.button .icon > * {
  flex-shrink: 0;
  inline-size: var(--box-xs);
  block-size: var(--box-xs);
  font-size: var(--text-body-xs);
}
.current .icon,
.item:hover .icon {
  color: inherit;
}

.label {
  flex: 1;
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* A count right after its label, in red: it needs attention. */
.label:has(+ .badge),
.text:has(+ .badge) {
  flex: 0 1 auto;
}
.badge {
  flex-shrink: 0;
  padding: 0 var(--control-xs-pad);
  border-radius: var(--radius-pill);
  background: var(--sidebar-badge, var(--destructive));
  color: var(--sidebar-badge-foreground, var(--destructive-foreground));
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  font-variant-numeric: tabular-nums;
}

/* NavSidebarButton: an item that is a button, with an optional second line. */
.button {
  inline-size: 100%;
  margin: 0;
  border: 0;
  background: transparent;
  font: inherit;
  text-align: start;
  cursor: var(--cursor-button);
}
.text {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-inline-size: 0;
}
.text .label {
  flex: none;
}
.description {
  overflow: hidden;
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--muted-foreground);
  text-overflow: ellipsis;
}
.end {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  font-size: var(--text-body-sm);
  color: var(--muted-foreground);
}
.end :where(svg) {
  font-size: var(--icon-md);
}
/* A tenant switcher: the name in medium weight, its chevron right after it. */
.switcher {
  color: var(--foreground);
  font-weight: 500;
}
.switcher .text {
  flex: 0 1 auto;
}
.switcher .end {
  margin-inline-start: calc(var(--space-1) - var(--space-inline));
}
/* A company, not a person: a rounded square rather than a circle. */
.switcher .icon > * {
  border-radius: var(--radius-sm);
}
/* As an input: a search button that opens a command palette. Its padding
   gives back the border's pixel, so the icon stays on the column. */
.field {
  padding-inline: calc(var(--space-inline) - 1px);
  border: 1px solid var(--sidebar-field-border, var(--input));
  border-radius: var(--radius-field);
  background: var(--sidebar-field, var(--card));
  color: var(--muted-foreground);
}
.field:hover {
  border-color: var(--field-border);
  background: var(--sidebar-field, var(--card));
}
/* Show more is a quiet control, at the category label's size. */
.more {
  color: var(--muted-foreground);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
}

.collapsed .item {
  justify-content: center;
  padding: 0;
}
.collapsed .label,
.collapsed .badge,
.collapsed .text,
.collapsed .end {
  display: none;
}
.collapsed .field {
  padding: 0;
  border-color: transparent;
  background: transparent;
}

/* No rule above it, as in the Claude apps: the body scrolls under it. Rows
   (notifications, help, the account) under each other, 2px apart like the
   items. */
.footer {
  display: flex;
  flex-direction: column;
  gap: var(--space-0-5);
  margin-block-start: var(--space-inline);
}

@media (pointer: coarse) {
  .item {
    min-block-size: var(--target-coarse);
  }
  /* No hover to reveal them on touch. */
  .groupAction,
  .groupChevron {
    opacity: 1;
  }
}
